import requests, zipfile, io

def fetch(url, timeout=60):
  r=requests.get(url,timeout=timeout)
  r.raise_for_status()
  return r.content

def build_zip(name_to_url):
  ok,fail={},{}
  for name,url in name_to_url.items():
    try: ok[name]=fetch(url)
    except Exception as e: fail[name]=str(e)
  buf=io.BytesIO()
  with zipfile.ZipFile(buf,'w',compression=zipfile.ZIP_DEFLATED) as z:
    for name,data in ok.items(): z.writestr(name,data)
  return {'zipped':len(ok),'failed':fail,'zip_bytes':buf.getvalue()}
